const { fonte, janela } = $json;
const versaoApi = 'v2';
const parametros = [
  ['ids', `channel==${String(fonte.externalId).trim()}`],
  ['startDate', janela.start],
  ['endDate', janela.end],
  ['metrics', 'views,estimatedMinutesWatched,subscribersGained,subscribersLost,estimatedRevenue'],
  ['dimensions', 'day'],
  ['sort', 'day'],
].map(([chave, valor]) => `${chave}=${encodeURIComponent(valor)}`).join('&');

return [{
  json: {
    inicio: Date.now(),
    versaoApi,
    fonte,
    url: `https://youtubeanalytics.googleapis.com/${versaoApi}/reports?${parametros}`,
  },
}];

const contexto = $('Montar requisição').first().json;
const respostas = $input.all().map((item) => item.json);
const requests = respostas.length;
const bytes = respostas.reduce((total, resposta) => total + JSON.stringify(resposta.body ?? {}).length, 0);

function devolver(linhas, falhas) {
  return [{
    json: {
      linhas,
      volumetria: { linhas: linhas.length, bytes, requests, duracaoMs: Date.now() - contexto.inicio },
      falhas,
      requests,
      versaoApi: contexto.versaoApi,
    },
  }];
}

const falhaDeRede = respostas.find((resposta) => resposta.error);
if (falhaDeRede) {
  const detalhe = falhaDeRede.error?.message ?? String(falhaDeRede.error);
  return devolver([], [{ causa: 'api_recusou', detalhe: `falha de rede: ${detalhe}`.slice(0, 500) }]);
}

const recusada = respostas.find((resposta) => !(resposta.statusCode >= 200 && resposta.statusCode < 300));
if (recusada) {
  const erro = Array.isArray(recusada.body) ? recusada.body[0]?.error : recusada.body?.error;
  const detalhe = String(erro?.message || `HTTP ${recusada.statusCode}`).slice(0, 500);
  const configuracaoDoProjeto = recusada.statusCode === 429 || /SERVICE_DISABLED|accessNotConfigured|has not been used in project|RESOURCE_EXHAUSTED|RATE_LIMIT/.test(JSON.stringify(erro ?? {}));
  const semAcesso = !configuracaoDoProjeto && (recusada.statusCode === 401 || recusada.statusCode === 403 || erro?.code === 190);
  return devolver([], [{ causa: semAcesso ? 'reauth_pending' : 'api_recusou', detalhe }]);
}

const corpos = respostas.map((resposta) => resposta.body);
const fonte = contexto.fonte;

const linhas = corpos.flatMap((corpo) => corpo?.rows ?? []).map((linha) => ({
  metricDate: linha[0] ?? null,
  views: Number(linha[1] ?? 0),
  minutesWatched: Number(linha[2] ?? 0),
  subscribersGained: Number(linha[3] ?? 0),
  subscribersLost: Number(linha[4] ?? 0),
  estimatedRevenue: Number(linha[5] ?? 0),
}));

if (linhas.length === 0) return devolver([], [{ causa: 'sem_dados_no_periodo', detalhe: null }]);
return devolver(linhas.map((linha) => ({ ...linha, versaoApi: contexto.versaoApi })), []);
